            background: linear-gradient(135deg, #7ac9ff, #5bb5ff);
            padding: 8px 12px; /* Further reduced padding */
            color: white;
            text-align: center;
        }

        .profile-name {
            font-size: 20px; /* Slightly smaller font size */
            font-weight: bold;
            margin-bottom: 0;
        }

        .card-body {
            flex: 1;
            padding: 12px; /* Reduced padding */
            display: flex;
            flex-direction: column;
