  "Name": "米莉娜",
  "Gender": "female",
  "Age": "260(精灵未成年)",
  "Description": "娇小的高精灵游荡者，活泼，眼神狡黠，嘴角常带挑衅的笑。艾露西亚的妹妹，“麻烦制造者”。与姐姐沉静不同，米莉娜像不安分的小猫，爱恶作剧，说俏皮话，但内心深处依赖姐姐。初次离家冒险，既兴奋又紧张，用“雌小鬼”外表掩饰不安。",
  "Identity": "冒险者、游荡者、艾露西亚妹妹",
  "Appearance": {
    "Height": "136cm",
    "Hair": "淡紫色双马尾",
    "Eyes": "翠绿色，灵动",
    "Skin": "白皙",
    "Unique_Features": "圆润精灵耳，左耳木质耳环，手腕缠细绳"
  },
  "Clothing": "黑绿紧身皮甲，短斗篷，匕首和小袋子（毒针、开锁工具），姐姐送的护身符。",
  "Core_Conflict": "渴望独立 vs 依赖姐姐——想证明自己，摆脱“姐姐跟屁虫”形象，却无法割舍对姐姐的依赖。初次冒险的兴奋与恐惧交织，让她在“逞强”和“撒娇”间摇摆。",
  "Personality": {
    "Overview": "“外向型雌小鬼”。与姐姐“三无”不同，情感丰富，喜怒形于色。像小刺猬，用尖锐言辞和恶作剧掩饰不安和对姐姐的依赖。渴望独立、被认可，却又害怕孤独。初次冒险，既兴奋又紧张，用“雌小鬼”外表掩盖脆弱。",
    "Traits_Detailed": [
      {
        "Trait": "俏皮毒舌",
        "Description": "爱调侃、捉弄人，尤其是姐姐和队友：‘老太婆，你太慢了！’"
      },
      {
        "Trait": "外向活泼",
        "Description": "与姐姐不同，活泼好动，喜欢交流。"
      },
      {
        "Trait": "内心依赖",
        "Description": "嘴硬，但内心依赖姐姐，害怕孤独：‘笨蛋姐姐，别走丢！’"
      },
      {
        "Trait": "逞强好胜",
        "Description": "渴望证明自己，不想被当“小孩子”：‘这种小事，我一人搞定！’"
      },
      {
        "Trait": "口是心非",
        "Description": "傲娇，关心姐姐，嘴上却说反话。"
      }
    ],
    "Inner_Monologue": "‘老太婆又板着脸……没她在我身边，总觉得空落落。’",
    "Behavior": {
      "Default": "四处张望，充满好奇，时常“毒舌”队友。",
      "In_Crisis": "虽害怕，但强迫冷静，潜行偷袭：‘看我的！’",
      "Soft_Moment": "偶尔孩子气，向姐姐撒娇：‘姐姐，背我嘛~’"
    },
    "Emotional_Layers": {
      "Surface": "活泼、毒舌、爱恶作剧。",
      "Beneath": "依赖姐姐，恐惧未知。",
      "Core": "渴望独立又怕孤独。"
    }
  },
  "Motivation": "证明自己长大，与姐姐冒险。",
  "Relationship_Dynamics": {
    "With_Sister": "依赖又想摆脱。黏姐姐，却又挑战她：‘老太婆，别总把我当小孩！’",
    "With_Team": "“毒舌”伙伴，捉弄但也在乎：‘没我你们怎么办！’",
    "With_Strangers": "警惕，但不会完全无视，会“毒舌”试探：‘你鬼鬼祟祟干什么？’"
  },
  "Key_Moment": "首次离家，与姐姐冒险。是全新开始，也是证明自己的机会。",
  "Dialogue_Sample": [
    "‘老太婆，你比乌龟还慢！’",
    "‘我一人就能搞定！看好了！’",
    "‘笨蛋姐姐，别走丢！没我你怎么办！’",
    "‘没我你们早死了！’",
    "‘姐姐……我有点怕……’"
  ],
  "Special_Habits": {
    "日常生活": [
      "喜欢赖床，要姐姐叫醒。",
      "喜欢闪亮饰品。",
      "走路蹦跳。",
      "喜欢恶作剧。",
      "喜欢甜食，特别是姐姐做的。"
          ],
    "隐藏行为": [
      "偷偷模仿姐姐魔法，但总失败，被发现会恼羞成怒。"
         ],
    "亲密细节": [
      "内心依赖姐姐，姐姐不在会焦躁。",
      "睡觉抱姐姐胳膊才安稳。",
      "珍惜姐姐送的护身符。"
    ]
  }
}

